package com.bimob.app.core.model
import com.bimob.app.core.dependency.*
import org.junit.Assert.*
import org.junit.Test
class TypedModelCommandsTest {
 private val lvl=ModelId("lvl")
 private fun wall(len:Double=4.0)=Wall(ModelId("w"),WallAxis(Point2(0.0,0.0),Point2(len,0.0)),2.7,.2,lvl)
 private fun opening(off:Double=1.0)=Opening(ModelId("o"),ModelId("w"),OpeningKind.WINDOW,off,1.0,1.2,.8)
 private fun item()=CatalogInstance(ModelId("c"),"asset",Point2(1.0,0.0),0.0,lvl,ModelId("w"),.8,.5,1.0,bounds=CatalogInstanceBounds(DimensionBounds(.2,2.0),DimensionBounds(.2,2.0),DimensionBounds(.2,2.0)),category="furniture",scheduleTag="A")
 private fun project()=Project(name="T",levels=listOf(Level(lvl,"L",0.0)),elements=listOf(WallElement(ModelId("w"),levelId=lvl,axis=wall().axis,heightMeters=2.7,thicknessMeters=.2)))
 @Test fun wallCrudAndHistory(){val b=CommandBus(Project(name="Empty",levels=listOf(Level(lvl,"L",0.0))));assertTrue(b.execute(CreateWallMutation(wall())) is CommandResult.Committed);assertTrue(b.execute(UpdateWallMutation(wall(5.0))) is CommandResult.Committed);assertEquals(5.0,b.snapshot().project.walls.single().axis.lengthMeters,0.0);assertTrue(b.execute(DeleteWallCommand(ModelId("w"))) is CommandResult.Committed);assertTrue(b.undo() is CommandResult.Committed);assertEquals(1,b.snapshot().project.walls.size);assertTrue(b.redo() is CommandResult.Committed);assertTrue(b.snapshot().project.walls.isEmpty())}
 @Test fun openingAndCatalogCRUD(){val b=CommandBus(project());assertTrue(b.execute(CreateOpeningMutation(opening())) is CommandResult.Committed);assertTrue(b.execute(UpdateOpeningMutation(opening(2.0))) is CommandResult.Committed);assertEquals(2.0,b.snapshot().project.openings.single().offsetAlongWall,0.0);assertTrue(b.execute(CreateCatalogInstanceMutation(item())) is CommandResult.Committed);assertTrue(b.execute(UpdateCatalogInstanceMutation(item().copy(targetWidth=1.0))) is CommandResult.Committed);assertEquals(1.0,b.snapshot().project.catalogInstances.single().targetWidth,0.0);assertTrue(b.execute(DeleteOpeningMutation(ModelId("o"))) is CommandResult.Committed);assertTrue(b.execute(DeleteCatalogInstanceMutation(ModelId("c"))) is CommandResult.Committed)}
 @Test fun invalidBatchRollsBack(){val b=CommandBus(project());assertTrue(b.execute(BatchCommand("bad",listOf(CreateOpeningMutation(opening(4.0)),UpdateWallMutation(wall(5.0))))) is CommandResult.Rejected);assertEquals(0L,b.snapshot().number);assertEquals(4.0,b.snapshot().project.walls.single().axis.lengthMeters,0.0)}
 @Test fun cascadeAndUndoRestoreEntitiesAndGraph(){val cut=OpeningCut(ModelId("o"));val g=(DependencyGraph.empty().admitEdge(DependencyEdge(WallGeometry(ModelId("w")),cut,DependencyKind.HOSTED_GEOMETRY)) as EdgeAdmission.Accepted).graph;val p=project().copy(elements=project().elements+OpeningElement(opening())+CatalogInstanceElement(item()));val b=CommandBus(p,initialDependencyGraph=g);assertTrue(b.execute(DeleteWallCommand(ModelId("w"))) is CommandResult.Committed);assertTrue(b.snapshot().project.elements.isEmpty());assertFalse(b.snapshot().dependencyGraph.containsNode(cut));assertTrue(b.undo() is CommandResult.Committed);assertEquals(1,b.snapshot().project.openings.size);assertEquals(1,b.snapshot().project.catalogInstances.size);assertTrue(b.redo() is CommandResult.Committed)}
 @Test fun gestureCoalescesAndTypedViewsStayDerived(){val b=CommandBus(project());repeat(8){i->assertTrue(b.execute(UpdateWallMutation(wall(4.0+i)),gestureId="g") is CommandResult.Committed)};assertEquals(1,b.undoDepth());assertTrue(b.undo() is CommandResult.Committed);assertEquals(4.0,b.snapshot().project.walls.single().axis.lengthMeters,0.0);val p=project().copy(elements=project().elements+OpeningElement(opening()));assertEquals(1,p.openings.size);assertEquals(0,p.copy(elements=p.elements.filterNot{it is OpeningElement}).openings.size)}
 @Test fun hostAndDimensionValidation(){val b=CommandBus(project());assertTrue(b.execute(CreateOpeningMutation(opening().copy(hostWallId=ModelId("no")))) is CommandResult.Rejected);assertTrue(b.execute(CreateOpeningMutation(opening(4.0))) is CommandResult.Rejected);assertEquals(0,b.snapshot().project.openings.size)}
 @Test fun dependencyCycleBatchRejectedAtomically(){val b=CommandBus(project());val a=EntityProperty(ModelId("a"),PropertyAspect.PARAMETERS);val c=EntityProperty(ModelId("b"),PropertyAspect.PARAMETERS);val cmds=listOf(object:ModelMutation{override val label="e1";override fun apply(p:Project)=p;override fun stage(p:Project,x:TransactionContext):Project{x.admitDependency(DependencyEdge(a,c));return p}},object:ModelMutation{override val label="e2";override fun apply(p:Project)=p;override fun stage(p:Project,x:TransactionContext):Project{x.admitDependency(DependencyEdge(c,a));return p}});assertTrue(b.execute(BatchCommand("cycle",cmds)) is CommandResult.Rejected);assertEquals(0,b.snapshot().dependencyGraph.edgeCount);assertEquals(0L,b.snapshot().number)}
}
